using System;
using System.IO;

public class ReportGenerator
{
    public void GenerateReport(SummaryReport report, bool exportToCsv = false, string filePath = null)
    {
        // Existing functionality: Output summary report to console
        Console.WriteLine("Report Summary:");
        Console.WriteLine(report.ToString());

        // New functionality: Export to CSV if requested
        if (exportToCsv)
        {
            if (string.IsNullOrEmpty(filePath))
            {
                filePath = "report_output.csv";
            }

            try
            {
                // Assuming SummaryReport has properties that can be serialized.
                // This is a generic implementation; adjust property names as needed.
                using (var writer = new StreamWriter(filePath))
                {
                    // Write header
                    writer.WriteLine("Field,Value");

                    // Write content based on report data.
                    // Note: Since SummaryReport structure isn't defined, 
                    // we assume it has a method or properties to iterate over.
                    // For demonstration, we'll write the string representation 
                    // or specific fields if available.

                    // Example: If report has a dictionary or properties, you would iterate here.
                    // For now, we write a placeholder or the string content if it's simple.
                    // A more robust solution would require knowing the SummaryReport structure.

                    // Assuming report.ToString() returns a structured string or we access specific fields:
                    // Here we simply write the report's string representation as a single value for demonstration.
                    // In a real scenario, you would parse report fields like:
                    // writer.WriteLine($"Date,{report.Date}");
                    // writer.WriteLine($"Total,{report.Total}");

                    writer.WriteLine($"Content,{report.ToString().Replace(",", ";")}"); // Escape commas if necessary
                }

                Console.WriteLine($"Report successfully exported to {filePath}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error exporting report to CSV: {ex.Message}");
            }
        }
    }
}

